import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest'
import { server } from '../test/mocks/server'
import { errorHandlers } from '../test/mocks/handlers'
import { fetchAssignments, rewriteCanvasNextLink } from './canvas'
import { useSettingsStore } from '../store/settingsStore'

describe('fetchAssignments', () => {
  beforeEach(() => {
    vi.useFakeTimers()
    vi.setSystemTime(new Date('2025-02-01T12:00:00Z'))

    // Set up mock settings before each test
    useSettingsStore.setState({
      canvasInstances: [{
        id: 'test-instance',
        name: 'Test School',
        token: 'test-token',
        url: 'test.instructure.com',
      }],
      timeframeDays: 30,
    })
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('fetches and transforms per-course assignments', async () => {
    const assignments = await fetchAssignments()

    expect(assignments).toHaveLength(2)
    expect(assignments[0]).toMatchObject({
      id: 'test-instance:1001',
      name: 'Homework 1',
      course_name: 'Intro to Computer Science',
    })
    expect(assignments[1]).toMatchObject({
      id: 'test-instance:1002',
      name: 'Quiz 2',
      course_name: 'Calculus I',
    })
  })

  it('handles all_day_date by converting to ISO format', async () => {
    const assignments = await fetchAssignments()

    // all_day_date should be converted to ISO format with T23:59:59Z
    expect(assignments[0].due_at).toBe('2025-02-10T23:59:59Z')
  })

  it('uses start_at/end_at when all_day_date is null', async () => {
    const assignments = await fetchAssignments()

    // Should use end_at when all_day_date is null
    expect(assignments[1].due_at).toBe('2025-02-15T11:00:00Z')
  })

  it('throws error on 401 unauthorized', async () => {
    server.use(errorHandlers.unauthorized)

    await expect(fetchAssignments()).rejects.toThrow('Test School: Invalid Canvas token')
  })

  it('throws error on server errors', async () => {
    server.use(errorHandlers.serverError)

    await expect(fetchAssignments()).rejects.toThrow('Test School: Canvas API error: 500')
  })

  it('rejects an unsafe pagination link before following it', async () => {
    server.use(errorHandlers.invalidPaginationLink)

    await expect(fetchAssignments()).rejects.toThrow(
      'Test School: Canvas returned an invalid pagination link'
    )
  })

  it('throws when every course returns malformed assignment data', async () => {
    server.use(errorHandlers.invalidJson)

    await expect(fetchAssignments()).rejects.toThrow(
      'Test School: Canvas returned an invalid JSON response'
    )
  })

  it('keeps successful courses when one course returns malformed data', async () => {
    server.use(errorHandlers.oneInvalidCourse)

    await expect(fetchAssignments()).resolves.toEqual([
      expect.objectContaining({
        id: 'test-instance:1002',
        course_name: 'Calculus I',
      }),
    ])
  })
})

describe('rewriteCanvasNextLink', () => {
  it('rewrites absolute and root-relative Canvas API links through the proxy', () => {
    expect(rewriteCanvasNextLink(
      'https://school.instructure.com/api/v1/courses?page=2&per_page=100'
    )).toBe('/api/canvas/courses?page=2&per_page=100')
    expect(rewriteCanvasNextLink('/api/v1/courses?page=3')).toBe(
      '/api/canvas/courses?page=3'
    )
  })

  it('strips an unexpected upstream host instead of sending it the Canvas token', () => {
    expect(rewriteCanvasNextLink(
      'https://attacker.example/api/v1/courses?page=2'
    )).toBe('/api/canvas/courses?page=2')
  })

  it.each([
    'https://attacker.example/collect?page=2',
    'javascript:alert(1)',
    '/not-the-canvas-api?page=2',
  ])('rejects pagination links outside the Canvas API: %s', (link) => {
    expect(() => rewriteCanvasNextLink(link)).toThrow(
      'Canvas returned an invalid pagination link'
    )
  })
})

import { z } from 'zod'
import { toLocalDateString } from '../utils/dateUtils'
import { useSettingsStore, type CanvasInstance } from '../store/settingsStore'

const CourseSchema = z.object({
  id: z.number(),
  name: z.string(),
})

const AssignmentSchema = z.object({
  id: z.number(),
  name: z.string(),
  due_at: z.string().nullable(),
})

export interface CanvasAssignment {
  id: string
  name: string
  due_at: string | null
  course_id: string
  course_name: string
}

/**
 * Parse the Link header to find the "next" page URL.
 */
function parseNextLink(linkHeader: string | null): string | null {
  if (!linkHeader) return null
  const match = linkHeader.match(/<([^>]+)>;\s*rel="next"/)
  return match?.[1] ?? null
}

/**
 * Convert Canvas pagination URLs back into a same-origin proxy request.
 * Never return an upstream URL because the caller attaches the Canvas token.
 */
export function rewriteCanvasNextLink(nextLink: string): string {
  let parsed: URL
  try {
    parsed = new URL(nextLink, 'https://canvas.invalid')
  } catch {
    throw new Error('Canvas returned an invalid pagination link')
  }

  if (
    (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') ||
    (parsed.pathname !== '/api/v1' && !parsed.pathname.startsWith('/api/v1/'))
  ) {
    throw new Error('Canvas returned an invalid pagination link')
  }

  const apiPath = parsed.pathname.slice('/api/v1'.length) || '/'
  return `/api/canvas${apiPath}${parsed.search}`
}

/**
 * Fetch all pages from a paginated Canvas API endpoint.
 */
async function fetchAllPages(url: string, headers: Record<string, string>): Promise<unknown[]> {
  const results: unknown[] = []
  let nextUrl: string | null = url

  while (nextUrl) {
    const res = await fetch(nextUrl, { headers })
    if (!res.ok) {
      if (res.status === 401) throw new Error('Invalid Canvas token')
      throw new Error(`Canvas API error: ${res.status}`)
    }

    let data: unknown
    try {
      data = await res.json()
    } catch {
      throw new Error('Canvas returned an invalid JSON response')
    }
    if (!Array.isArray(data)) break
    results.push(...data)

    const linkHeader = res.headers.get('Link')
    const nextLink = parseNextLink(linkHeader)
    if (nextLink) {
      nextUrl = rewriteCanvasNextLink(nextLink)
    } else {
      nextUrl = null
    }
  }

  return results
}

/**
 * Fetch assignments from a single Canvas instance
 */
async function fetchFromInstance(instance: CanvasInstance): Promise<CanvasAssignment[]> {
  const headers: Record<string, string> = {
    'Authorization': `Bearer ${instance.token}`,
    'X-Canvas-Host': instance.url,
  }

  // Get date range: today to N days out based on user's timeframe setting
  const { timeframeDays } = useSettingsStore.getState()
  const today = new Date()
  const endDay = new Date(Date.now() + timeframeDays * 24 * 60 * 60 * 1000)
  const startDate = toLocalDateString(today)
  const endDate = toLocalDateString(endDay)

  // Fetch all active courses with pagination
  const rawCourses = await fetchAllPages('/api/canvas/courses?enrollment_state=active&per_page=100', headers)

  const courses = rawCourses
    .map((course) => {
      const parsed = CourseSchema.safeParse(course)
      return parsed.success ? parsed.data : null
    })
    .filter((c): c is z.infer<typeof CourseSchema> => c !== null)

  if (courses.length === 0) {
    return []
  }

  // Fetch assignments from each course in parallel
  // Uses per-course endpoint instead of calendar_events (which some Canvas instances restrict)
  const courseResults = await Promise.allSettled(
    courses.map(async (course) => {
      const url = `/api/canvas/courses/${course.id}/assignments?per_page=100&order_by=due_at`
      const rawAssignments = await fetchAllPages(url, headers)
      return { course, assignments: rawAssignments }
    })
  )

  const successfulCourseRequests = courseResults.filter(
    (result): result is PromiseFulfilledResult<{
      course: z.infer<typeof CourseSchema>
      assignments: unknown[]
    }> => result.status === 'fulfilled'
  )

  if (successfulCourseRequests.length === 0) {
    const firstFailure = courseResults.find(
      (result): result is PromiseRejectedResult => result.status === 'rejected'
    )
    if (firstFailure?.reason instanceof Error) throw firstFailure.reason
    throw new Error('Failed to fetch assignments from Canvas')
  }

  const allAssignments: CanvasAssignment[] = []

  for (const result of successfulCourseRequests) {
    const { course, assignments } = result.value

    for (const raw of assignments) {
      const parsed = AssignmentSchema.safeParse(raw)
      if (!parsed.success) continue

      const assignment = parsed.data
      if (!assignment.due_at) continue

      // Filter to assignments within the configured timeframe
      const dueDateStr = toLocalDateString(new Date(assignment.due_at))
      if (dueDateStr < startDate || dueDateStr > endDate) continue

      allAssignments.push({
        id: `${instance.id}:${assignment.id}`,
        name: assignment.name,
        due_at: assignment.due_at,
        course_id: String(course.id),
        course_name: course.name,
      })
    }
  }

  return allAssignments
}

/**
 * Fetch assignments from all configured Canvas instances
 */
export async function fetchAssignments(): Promise<CanvasAssignment[]> {
  const { canvasInstances } = useSettingsStore.getState()

  const validInstances = canvasInstances.filter(i => i.url && i.token)

  if (validInstances.length === 0) {
    throw new Error('No Canvas instances configured. Please add your schools in Settings.')
  }

  // Fetch from all instances in parallel
  const results = await Promise.allSettled(
    validInstances.map(instance => fetchFromInstance(instance))
  )

  // Collect all assignments and errors
  const allAssignments: CanvasAssignment[] = []
  const errors: string[] = []

  results.forEach((result, index) => {
    if (result.status === 'fulfilled') {
      allAssignments.push(...result.value)
    } else {
      errors.push(`${validInstances[index].name}: ${result.reason.message}`)
    }
  })

  // If all instances failed, throw an error
  if (allAssignments.length === 0 && errors.length > 0) {
    throw new Error(errors.join('; '))
  }

  // Log warnings for partial failures but still return results
  if (errors.length > 0) {
    console.warn('Some Canvas instances failed:', errors)
  }

  return allAssignments
}

import { http, HttpResponse } from 'msw'

const mockCourses = [
  { id: 123456, name: 'Intro to Computer Science' },
  { id: 789012, name: 'Calculus I' },
]

const mockAssignments = new Map([
  ['123456', [{ id: 1001, name: 'Homework 1', due_at: '2025-02-10T23:59:59Z' }]],
  ['789012', [{ id: 1002, name: 'Quiz 2', due_at: '2025-02-15T11:00:00Z' }]],
])

export const handlers = [
  http.get('/api/canvas/courses', ({ request }) => {
    const url = new URL(request.url)
    const enrollmentState = url.searchParams.get('enrollment_state')

    if (enrollmentState === 'active') {
      return HttpResponse.json(mockCourses)
    }
    return HttpResponse.json([])
  }),

  http.get('/api/canvas/courses/:courseId/assignments', ({ params }) => {
    return HttpResponse.json(mockAssignments.get(String(params.courseId)) ?? [])
  }),
]

export const errorHandlers = {
  unauthorized: http.get('/api/canvas/courses', () => {
    return new HttpResponse(null, { status: 401 })
  }),

  serverError: http.get('/api/canvas/courses', () => {
    return new HttpResponse(null, { status: 500 })
  }),

  invalidPaginationLink: http.get('/api/canvas/courses', () => {
    return HttpResponse.json(mockCourses, {
      headers: {
        Link: '<https://attacker.example/collect?page=2>; rel="next"',
      },
    })
  }),

  invalidJson: http.get('/api/canvas/courses/:courseId/assignments', () => {
    return new HttpResponse('not valid json', {
      headers: { 'Content-Type': 'application/json' },
    })
  }),

  oneInvalidCourse: http.get('/api/canvas/courses/:courseId/assignments', ({ params }) => {
    if (String(params.courseId) === '123456') {
      return new HttpResponse('not valid json', {
        headers: { 'Content-Type': 'application/json' },
      })
    }
    return HttpResponse.json(mockAssignments.get(String(params.courseId)) ?? [])
  }),
}
